509	#ifdef RBTREE_TEST_HOOKS
510	/* Test-only hooks for exercising rb_validate's negative paths (invariants
511	 * 1-5). Compiled in only when RBTREE_TEST_HOOKS is defined (test_rbtree's
512	 * build only, per the Makefile) so production/grading builds that compile
513	 * this file without the macro never see these symbols at all. Each hook
514	 * mutates only existing struct fields on nodes the tree already owns --
515	 * no allocation, no freeing -- so rb_destroy's pointer-only teardown walk
516	 * (left/right only; it never reads color, key contents, or t->size) stays
517	 * safe to call afterward regardless of which invariant was broken.
518	 *
519	 * rb_validate checks invariants in order (1: root black, 2: no red-red,
520	 * 3: black-height, 4: ordering, 5: size) and returns on the first failure,
521	 * which is what lets each hook below isolate its target invariant's return
522	 * code even when a mutation has a side effect on a later check. */
523	
524	/* Invariant 1: flip the root red. Root-color is checked first and
525	 * unconditionally, so this isolates invariant 1 regardless of anything
526	 * else about the tree. */
527	void rb_test_force_root_red(rbtree_t *t) {
528	    if (t != NULL && t->root != NULL) t->root->color = RED;
529	}
530	
531	/* Invariant 2: find a RED node with a real (non-NULL) BLACK child and flip
532	 * that child RED, producing a red-red pair. Returns 1 if found and
533	 * corrupted, 0 if the fixture didn't have the needed shape. */
534	static struct rb_node *find_red_with_black_child(struct rb_node *n) {
535	    if (n == NULL) return NULL;
536	    if (n->color == RED &&
537	        ((n->left != NULL && n->left->color == BLACK) ||
538	         (n->right != NULL && n->right->color == BLACK))) {
539	        return n;
540	    }
541	    struct rb_node *found = find_red_with_black_child(n->left);
542	    if (found != NULL) return found;
543	    return find_red_with_black_child(n->right);
544	}
545	
546	int rb_test_force_red_red(rbtree_t *t) {
547	    if (t == NULL) return 0;
548	    struct rb_node *p = find_red_with_black_child(t->root);
549	    if (p == NULL) return 0;
550	    struct rb_node *child = (p->left != NULL && p->left->color == BLACK)
551	                             ? p->left : p->right;
552	    child->color = RED;
553	    return 1;
554	}
555	
556	/* Invariant 3: find a non-root BLACK node whose parent is BLACK and whose
557	 * own children are both BLACK-or-NIL, then flip it RED. That perturbs only
558	 * that node's subtree's black count -- it can't create a red-red pair
559	 * (parent stays black, its own children stay black) and it doesn't touch
